// Read 27 adjacency masks and a deleted site. A necessary-only gate; never selects seven rows.
use std::io::{self,BufRead};
mod prior {include!("ramsey_deleted27_six_joint.rs");pub fn rows(a:&[u32;27],p:u32)->Vec<u32>{let mut r=vec![];maximal(a,p,0,0,&mut r);r}}
fn color(g:&[Vec<bool>],ns:&[usize],cap:usize)->bool {let mut cl:Vec<Vec<usize>>=vec![];for &v in ns{if let Some(c)=cl.iter_mut().find(|c|c.iter().all(|&u|!g[v][u])){c.push(v)}else{if cl.len()==cap{return false}cl.push(vec![v]);}}true}
fn gate(a:&[u32;27],p:u32)->(usize,usize,usize){let all=prior::rows(a,p);if all.iter().any(|s|s.count_ones()>=8){return (0,0,0)}let qs:Vec<_>=all.iter().filter(|s|s.count_ones()==7).collect();let rows:Vec<_>=all.iter().copied().filter(|s|s.count_ones()>=6).collect();let n=rows.len();let w=(qs.len()+63)/64;let mut miss=vec![vec![0u64;w];n];for(i,&s)in rows.iter().enumerate(){for(j,&&q)in qs.iter().enumerate(){if q&s==0{miss[i][j/64]|=1<<(j%64)}}}if miss.iter().any(|m|m.iter().all(|&x|x==0)){return (3,n,n)}let mut g=vec![vec![false;n];n];let mut deg=vec![0;n];for i in 0..n{for j in 0..i{if (0..w).all(|h|miss[i][h]&miss[j][h]==0){g[i][j]=true;g[j][i]=true;deg[i]+=1;deg[j]+=1}}}let mut vs:Vec<_>=(0..n).collect();vs.sort_by_key(|&v|std::cmp::Reverse(deg[v]));if color(&g,&vs,6){return (1,n,0)}loop{let left:Vec<_>=vs.iter().copied().filter(|&i|{let ns:Vec<_>=vs.iter().copied().filter(|&j|g[i][j]).collect();!color(&g,&ns,5)}).collect();if left.len()==vs.len(){return (3,n,left.len())}if left.len()<7||color(&g,&left,6){return (2,n,0)}vs=left}}
fn main(){for l in io::stdin().lock().lines(){let l=l.unwrap();let x:Vec<u32>=l.split_whitespace().map(|s|s.parse().unwrap()).collect();let id=x[0];let z=x[1];let p=((1u32<<27)-1)^(1<<z);let a:[u32;27]=x[2..].try_into().unwrap();for u in 0..27{for v in 0..u{if (u as u32)==z||(v as u32)==z{continue}let old=a[u]>>v&1;if old==0&&a[u]&a[v]&p!=0{continue}let mut b=[0u32;27];for j in 0..27{b[j]=p&!(a[j]|1<<j)}b[u]^=1<<v;b[v]^=1<<u;let (k,n,m)=gate(&b,p);println!("{} {} {} {} {} {} {} {}",id,z,v,u,old,k,n,m)}}}}
